/* =========================================================
   4chan-neXT — dark monospace UI
   scoped to board pages
   ========================================================= */

:root {
  --sidebar-width: 50px;

  --bg: #181922;
  --sidebar: #171820;
  --panel: #20212c;
  --panel-hover: #252632;
  --panel-active: #292a36;

  --border: #2c2d38;
  --border-soft: #24252f;

  --text: #d9dbea;
  --muted: #969bad;

  --link: #b9a7e8;
  --link-hover: #d3c7f3;

  --green: #86b88a;
  --pink: #d78aa3;
  --yellow: #e6c76a;

  --quote: #93b38e;
}


/* =========================================================
   PAGE
   ========================================================= */

html:has(body[class*="board_"]),
body[class*="board_"] {
  background: var(--bg) !important;
  color: var(--text) !important;

  font-family:
    "IBM Plex Mono",
    "JetBrains Mono",
    "Cascadia Mono",
    "SFMono-Regular",
    Consolas,
    "Liberation Mono",
    monospace !important;

  font-size: 14px !important;
}

body[class*="board_"] {
  margin-left: var(--sidebar-width) !important;
  padding: 0 14px !important;
  box-sizing: border-box !important;
}


/* =========================================================
   LEFT SIDEBAR / FAVORITE BOARDS
   ========================================================= */

body[class*="board_"] #board-list {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;

  width: var(--sidebar-width) !important;
  height: 100vh !important;

  box-sizing: border-box !important;
  padding: 10px 6px !important;

  background: var(--sidebar) !important;
  border-right: 1px solid var(--border) !important;

  overflow-y: auto !important;
  overflow-x: hidden !important;

  z-index: 99999 !important;

  font-size: 14px !important;
}

body[class*="board_"] #custom-board-list {
  display: flex !important;
  flex-direction: column !important;
  gap: 2px !important;

  width: 100% !important;
  margin-top: 2px !important;

  white-space: normal !important;
}

body[class*="board_"] #board-list #custom-board-list a {
  display: block !important;

  width: 100% !important;
  box-sizing: border-box !important;

  padding: 7px 7px !important;
  margin: 0 !important;

  border-radius: 6px !important;

  background: transparent !important;
  color: var(--pink) !important;

  text-decoration: none !important;
  font-weight: 400 !important;
}

body[class*="board_"] #board-list #custom-board-list a:hover {
  background: var(--panel-hover) !important;
  color: #f0a0c6 !important;
  text-decoration: none !important;
}

body[class*="board_"] #board-list #custom-board-list a.current {
  background: var(--panel-active) !important;
  color: var(--green) !important;

  font-weight: 600 !important;

  box-shadow: inset 2px 0 0 var(--green) !important;
}


/* =========================================================
   ALL BOARDS BUTTON
   ========================================================= */

body[class*="board_"] #board-list .show-board-list-button {
  display: block !important;

  width: 100% !important;
  box-sizing: border-box !important;

  margin: 0 0 8px 0 !important;
  padding: 5px 3px !important;

  border-radius: 6px !important;

  background: var(--panel) !important;
  color: var(--muted) !important;

  text-align: center !important;
  text-decoration: none !important;
}

body[class*="board_"] #board-list .show-board-list-button:hover {
  background: var(--panel-hover) !important;
  color: var(--text) !important;
}


/* =========================================================
   ALL BOARDS FLYOUT
   ========================================================= */

body[class*="board_"] #full-board-list:not([hidden]) {
  position: fixed !important;

  top: 8px !important;
  left: var(--sidebar-width) !important;

  width: 360px !important;
  max-height: calc(100vh - 16px) !important;

  box-sizing: border-box !important;
  padding: 12px 14px !important;

  overflow-y: auto !important;
  overflow-x: hidden !important;

  background: var(--sidebar) !important;

  border: 1px solid var(--border) !important;
  border-radius: 8px !important;

  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4) !important;

  z-index: 100000 !important;

  white-space: normal !important;
  line-height: 1.8 !important;

  color: var(--muted) !important;
}

body[class*="board_"] #full-board-list .boardList {
  display: block !important;
  white-space: normal !important;
}

body[class*="board_"] #full-board-list .boardList a {
  display: inline-block !important;

  width: auto !important;

  margin: 2px 1px !important;
  padding: 2px 5px !important;

  border-radius: 4px !important;

  color: var(--pink) !important;
  background: transparent !important;

  text-decoration: none !important;
}

body[class*="board_"] #full-board-list .boardList a:hover {
  background: var(--panel-hover) !important;
  color: #f0a0c6 !important;
}

body[class*="board_"] #full-board-list .boardList a.current {
  background: var(--panel-active) !important;
  color: var(--green) !important;
}

body[class*="board_"] #full-board-list .hide-board-list-container {
  display: block !important;
  margin-bottom: 8px !important;
  text-align: right !important;
}

body[class*="board_"] #full-board-list .hide-board-list-button {
  display: inline-block !important;

  padding: 3px 7px !important;

  border-radius: 5px !important;

  background: var(--panel) !important;
  color: var(--muted) !important;

  text-decoration: none !important;
}

body[class*="board_"] #full-board-list .hide-board-list-button:hover {
  background: var(--panel-hover) !important;
  color: var(--text) !important;
}


/* =========================================================
   HEADER
   ========================================================= */

body[class*="board_"] #header-bar {
  left: var(--sidebar-width) !important;
  width: calc(100% - var(--sidebar-width)) !important;

  background: rgba(24, 25, 34, 0.96) !important;

  border-bottom: 1px solid var(--border) !important;

  box-shadow: none !important;

  color: var(--muted) !important;
}

body[class*="board_"] #header-bar a {
  color: var(--muted) !important;
}

body[class*="board_"] #header-bar a:hover {
  color: var(--text) !important;
}


/* =========================================================
   BOARD TITLE / BANNER
   ========================================================= */

body[class*="board_"] .boardBanner {
  margin-top: 28px !important;
}

body[class*="board_"] .boardTitle {
  color: var(--text) !important;

  font-weight: 500 !important;

  text-shadow: none !important;
}

body[class*="board_"] .boardSubtitle {
  color: var(--muted) !important;
}

body[class*="board_"] .boardBanner img {
  border-radius: 8px !important;
  opacity: 0.9 !important;
}


/* =========================================================
   POSTS
   ========================================================= */

body[class*="board_"] .post.reply,
body[class*="board_"] .reply {
  background: var(--panel) !important;

  color: var(--text) !important;

  border: 1px solid var(--border) !important;

  border-radius: 8px !important;

  box-shadow: none !important;

  padding: 9px 11px !important;
}

body[class*="board_"] .postContainer {
  margin-top: 5px !important;
  margin-bottom: 5px !important;
}

body[class*="board_"] .post.reply:hover,
body[class*="board_"] .reply:hover {
  border-color: #373846 !important;
}

body[class*="board_"] .post.op {
  color: var(--text) !important;
}


/* =========================================================
   POST TEXT
   ========================================================= */

body[class*="board_"] .postMessage {
  color: var(--text) !important;

  font-size: 14px !important;
  line-height: 1.55 !important;
}

body[class*="board_"] .name,
body[class*="board_"] .subject {
  color: var(--green) !important;
}

body[class*="board_"] .quote {
  color: var(--quote) !important;
}

body[class*="board_"] .deadlink {
  color: #777b8a !important;
}


/* =========================================================
   LINKS
   ========================================================= */

body[class*="board_"] a,
body[class*="board_"] .quotelink,
body[class*="board_"] .backlink,
body[class*="board_"] .fileText a {
  color: var(--link) !important;
}

body[class*="board_"] a:hover,
body[class*="board_"] .quotelink:hover,
body[class*="board_"] .backlink:hover,
body[class*="board_"] .fileText a:hover {
  color: var(--link-hover) !important;
}


/* =========================================================
   POST METADATA
   ========================================================= */

body[class*="board_"] .dateTime,
body[class*="board_"] .fileText,
body[class*="board_"] .posteruid,
body[class*="board_"] .capcode {
  color: var(--muted) !important;
  font-size: 12px !important;
}


/* =========================================================
   POST NUMBER — YELLOW
   ========================================================= */

body[class*="board_"] .postInfo .postNum,
body[class*="board_"] .postInfo .postNum *,
body[class*="board_"] .postNum,
body[class*="board_"] .postNum * {
  color: var(--yellow) !important;
  -webkit-text-fill-color: var(--yellow) !important;
  opacity: 1 !important;
}


/* =========================================================
   CATALOG
   ========================================================= */

body[class*="board_"] .catalog-thread,
body[class*="board_"] .catalogThread,
body[class*="board_"] div.thread.catalog-thread {
  background: transparent !important;

  color: var(--text) !important;

  border-radius: 8px !important;

  padding: 7px !important;

  font-size: 13px !important;
  line-height: 1.4 !important;
}

body[class*="board_"] .catalog-thread:hover,
body[class*="board_"] .catalogThread:hover {
  background: var(--panel) !important;
}

body[class*="board_"] .catalog-thread img,
body[class*="board_"] .catalogThread img {
  border-radius: 6px !important;
}

body[class*="board_"] .catalog-thread .subject,
body[class*="board_"] .catalogThread .subject {
  font-size: 13px !important;
  font-weight: 600 !important;
}


/* =========================================================
   FORMS / BUTTONS
   ========================================================= */

body[class*="board_"] button,
body[class*="board_"] input,
body[class*="board_"] select,
body[class*="board_"] textarea {
  background: var(--panel) !important;

  color: var(--text) !important;

  border: 1px solid var(--border) !important;

  border-radius: 6px !important;

  box-shadow: none !important;

  font-family: inherit !important;
  font-size: 13px !important;
}

body[class*="board_"] button:hover,
body[class*="board_"] input:hover,
body[class*="board_"] select:hover {
  border-color: #414250 !important;
}

body[class*="board_"] input:focus,
body[class*="board_"] textarea:focus,
body[class*="board_"] select:focus {
  outline: none !important;
  border-color: #646779 !important;
}


/* =========================================================
   THREAD WATCHER
   ========================================================= */

body[class*="board_"] #thread-watcher {
  position: fixed !important;

  left: 6px !important;
  right: auto !important;

  top: auto !important;
  bottom: 10px !important;

  width: calc(var(--sidebar-width) - 12px) !important;
  max-width: calc(var(--sidebar-width) - 12px) !important;

  box-sizing: border-box !important;

  background: var(--panel) !important;

  color: var(--text) !important;

  border: 1px solid var(--border) !important;

  border-radius: 8px !important;

  box-shadow: 0 6px 22px rgba(0, 0, 0, 0.28) !important;
}

body[class*="board_"] #thread-watcher .move {
  background: transparent !important;

  border-bottom: 1px solid var(--border) !important;

  color: var(--muted) !important;
}


/* =========================================================
   POPUPS / MENUS
   ========================================================= */

body[class*="board_"] .menu,
body[class*="board_"] .dialog,
body[class*="board_"] #settings,
body[class*="board_"] #settingsMenu,
body[class*="board_"] #hoverUI,
body[class*="board_"] #quote-preview {
  background: var(--panel) !important;

  color: var(--text) !important;

  border: 1px solid var(--border) !important;

  border-radius: 8px !important;

  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.35) !important;
}


/* =========================================================
   SEPARATORS
   ========================================================= */

body[class*="board_"] hr {
  border: 0 !important;
  border-top: 1px solid var(--border-soft) !important;
}

body[class*="board_"] hr.abovePostForm {
  border-top: 1px solid var(--border) !important;
}


/* =========================================================
   SCROLLBARS
   ========================================================= */

body[class*="board_"] * {
  scrollbar-color: #444653 transparent !important;
  scrollbar-width: thin !important;
}


/* =========================================================
   OLD 4CHAN NAV / FOOTER
   ========================================================= */

body[class*="board_"] #boardNavDesktop,
body[class*="board_"] #boardNavDesktopFoot {
  color: var(--muted) !important;
}

body[class*="board_"] #absbot,
body[class*="board_"] #footer-links {
  color: var(--muted) !important;
}

/* =========================================================
   CATALOG HOVER EXPANSION
   ========================================================= */

body[class*="board_"] .catalog-hover-expand .catalog-container:hover > .post,
body[class*="board_"] .catalog-hover-expand .catalog-container:hover .catalog-reply,
body[class*="board_"] .catalog-post.catalog-post:hover,
body[class*="board_"] .catalog-reply {
  background: var(--panel) !important;
  color: var(--text) !important;

  border: 1px solid var(--border) !important;
  border-radius: 8px !important;

  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35) !important;
}

/* text inside expanded catalog hover */
body[class*="board_"] .catalog-hover-expand .catalog-container:hover > .post .comment,
body[class*="board_"] .catalog-hover-expand .catalog-container:hover > .post .postMessage,
body[class*="board_"] .catalog-hover-expand .catalog-container:hover .catalog-reply .comment {
  background: transparent !important;
  color: var(--text) !important;
}

/* keep metadata dark-theme friendly */
body[class*="board_"] .catalog-hover-expand .catalog-container:hover > .post .dateTime,
body[class*="board_"] .catalog-hover-expand .catalog-container:hover > .post .fileText,
body[class*="board_"] .catalog-hover-expand .catalog-container:hover .catalog-reply .dateTime {
  color: var(--muted) !important;
}

body[class*="board_"] #hoverUI img {
  max-width: 50vw !important;
  max-height: 80vh !important;

  width: auto !important;
  height: auto !important;
}
